def choose_move(observation):
    def clamp(v):
        if v < -1:
            return -1
        if v > 1:
            return 1
        return v

    def is_num(x):
        return isinstance(x, (int, float)) and not isinstance(x, bool)

    def first_num_pair(x):
        if isinstance(x, (list, tuple)) and len(x) >= 2 and is_num(x[0]) and is_num(x[1]):
            return int(x[0]), int(x[1])
        if isinstance(x, dict):
            for a, b in (("x", "y"), ("row", "col"), ("r", "c"), ("i", "j")):
                if a in x and b in x and is_num(x[a]) and is_num(x[b]):
                    return int(x[a]), int(x[b])
        return None

    def extract_self_pos(obs):
        for keyset in (
            ("self_pos", "position", "pos", "agent_pos", "agent_position"),
            ("self", "me", "agent"),
        ):
            for k in keyset:
                v = obs.get(k) if isinstance(obs, dict) else None
                p = first_num_pair(v)
                if p is not None:
                    return p
                if isinstance(v, dict):
                    for kk in ("pos", "position", "loc", "location"):
                        p = first_num_pair(v.get(kk))
                        if p is not None:
                            return p
        if isinstance(obs, dict):
            for k in ("x", "y", "row", "col", "i", "j"):
                pass
            if is_num(obs.get("x")) and is_num(obs.get("y")):
                return int(obs["x"]), int(obs["y"])
        return None

    def collect_pairs(obj, out, depth=0):
        if depth > 4:
            return
        p = first_num_pair(obj)
        if p is not None:
            out.append(p)
            return
        if isinstance(obj, dict):
            for v in obj.values():
                collect_pairs(v, out, depth + 1)
        elif isinstance(obj, (list, tuple)):
            for v in obj:
                collect_pairs(v, out, depth + 1)

    def nearest(pos, points):
        best = None
        best_d = None
        x, y = pos
        for px, py in points:
            d = abs(px - x) + abs(py - y)
            if best_d is None or d < best_d:
                best_d = d
                best = (px, py)
        return best, best_d

    def sign(v):
        return 1 if v > 0 else (-1 if v < 0 else 0)

    obs = observation if isinstance(observation, dict) else {}
    me = extract_self_pos(obs)

    if me is None:
        # Fallback: deterministic no-op or slight move from any turn-like value.
        t = obs.get("turn", obs.get("step", 0))
        if is_num(t):
            m = int(t) % 4
            if m == 0:
                return [1, 0]
            if m == 1:
                return [0, 1]
            if m == 2:
                return [-1, 0]
            return [0, -1]
        return [0, 0]

    mx, my = me

    resource_keys = ("resources", "resource", "food", "targets", "objects", "items", "goals")
    enemy_keys = ("enemies", "enemy", "opponents", "opponent", "threats", "pursuers", "agents")
    territory_keys = ("territory", "frontier", "cells", "claims", "bases", "home")

    resources = []
    enemies = []
    territory = []

    for k in resource_keys:
