        if v is not None:
            collect_pairs(v, resources)

    for k in enemy_keys:
        v = obs.get(k)
        if v is not None:
            collect_pairs(v, enemies)

    for k in territory_keys:
        v = obs.get(k)
        if v is not None:
            collect_pairs(v, territory)

    # Remove own position if accidentally captured.
    resources = [p for p in resources if p != me]
    enemies = [p for p in enemies if p != me]
    territory = [p for p in territory if p != me]

    # If a grid is available, infer local threats/targets from nearby cells.
    grid = obs.get("grid")
    if isinstance(grid, (list, tuple)) and grid and isinstance(grid[0], (list, tuple)):
        h = len(grid)
        w = len(grid[0]) if grid[0] else 0
        for i in range(max(0, my - 4), min(h, my + 5)):
            row = grid[i]
            if not isinstance(row, (list, tuple)):
                continue
            for j in range(max(0, mx - 4), min(w, mx + 5)):
                v = row[j]
                if is_num(v):
                    iv = int(v)
                    # Heuristic: positive cells are targets/resources, negative are threats.
                    if iv > 0:
                        resources.append((j, i))
                    elif iv < 0:
                        enemies.append((j, i))

    # Prefer escape if enemy is very close.
    enemy, ed = nearest(me, enemies) if enemies else (None, None)
    resource, rd = nearest(me, resources) if resources else (None, None)
    terr, td = nearest(me, territory) if territory else (None, None)

    move_x = 0
    move_y = 0

    if ed is not None and ed <= 2:
